#include <bits/stdc++.h>
using namespace std;using I=long long;using P=array<I,9>;constexpr I MOD=1000000007;using Key=array<uint32_t,19>;struct Rec{int source=-1,macro=-1;};struct Hash{size_t operator()(const Key&a)const{uint64_t h=1469598103934665603ULL;for(auto v:a){h^=v;h*=1099511628211ULL;}return h;}};
P mv(P p,char c){auto[h,s,e,L,R,d,C,b,T]=p;P q;if(c=='O')q={h,s,0,L,2*R,d,2*C,2*b,3*T};else if(c=='Z')q={h+R-e,s,d,L+b,2*R-d,d,2*C+2*T-2*L,2*b,3*T-b};else q={h+R-e,s,h-e,C-L,h+R,h,2*C+2*T-2*L,C,T+C};for(auto&x:q){x%=MOD;if(x<0)x+=MOD;}return q;}
int main(int argc,char**argv){int D=argc>2?atoi(argv[2]):3;ifstream in(argv[1]);int ix,mask,n;P p;vector<P>src;while(in>>ix>>mask>>n){for(auto&x:p)in>>x;src.push_back(p);}vector<string>words;function<void(string)>gen=[&](string s){if(s.size())words.push_back(s);if((int)s.size()==D)return;for(char c:string("OZJ"))gen(s+c);};gen("");vector<bool>has;for(auto w:words)has.push_back(w.find('J')!=string::npos);
unordered_map<Key,array<Rec,2>,Hash>bank;bank.reserve(src.size()*words.size());long long cases=0,hits=0;set<Key>emitted;
for(int i=0;i<(int)src.size();i++){P start=src[i];int r=start[1]%3;I c=(start[1]+2*r)/3;for(int j=0;j<(int)words.size();j++){Key key;P p=start;for(int k=0;k<19;k++){key[k]=(p[0]+p[3]-c+MOD)%MOD;for(char ch:words[j])p=mv(p,ch);}auto &slots=bank[key];auto&slot=slots[r-1];if(slot.source<0||(has[j]&&!has[slot.macro]))slot={i,j};if(slots[0].source>=0&&slots[1].source>=0&&(has[slots[0].macro]||has[slots[1].macro])&&emitted.insert(key).second){hits++;cout<<"MATCH "<<key[0]<<"\n";for(auto z:slots)cout<<z.source<<" "<<words[z.macro]<<"\n";cout<<flush;}cases++;}if(i%10000==0)cerr<<"sources "<<i<<" keys "<<bank.size()<<" hits "<<hits<<"\n";}
cerr<<"FINAL sources "<<src.size()<<" macros "<<words.size()<<" cases "<<cases<<" keys "<<bank.size()<<" hits "<<hits<<"\n";
}
